static const char METECH_WEB_UI[] = R"HTML(<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Metech Camera</title><style>:root{--bg:#07111d;--card:#0d1c2d;--line:#203752;--text:#eaf2fb;--muted:#a0b4ca;--blue:#176daf}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px system-ui,sans-serif}.wrap{max-width:1100px;margin:auto;padding:15px}.top,.head,.actions,.address,.pills,.row{display:flex;align-items:center;gap:9px}.top,.head{justify-content:space-between}.grid{display:grid;grid-template-columns:1.4fr .9fr;gap:15px}.card{margin-top:15px;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:14px}.camera{padding:0;overflow:hidden}.head,.actions{padding:12px 14px}.live{aspect-ratio:1.25;background:#02070d}.live img{width:100%;height:100%;object-fit:contain}.actions,.address,.pills{flex-wrap:wrap}button,input,select{min-height:38px;border-radius:8px;font:inherit}button{border:0;padding:8px 10px;background:#21364c;color:var(--text);font-weight:650;cursor:pointer}.primary{background:var(--blue)}button:disabled{opacity:.5;cursor:default}:focus-visible{outline:2px solid #87c9ff;outline-offset:3px}.stats{display:grid;grid-template-columns:1fr 1fr;gap:8px}.stat{padding:9px;background:#091727;border:1px solid #1a3049;border-radius:10px}.stat b{display:block;margin-top:3px;overflow-wrap:anywhere}.muted,.note{color:var(--muted);font-size:13px}input,select{background:#091727;border:1px solid var(--line);color:var(--text);padding:7px}.ip{flex:1;min-width:150px;font:13px ui-monospace,monospace;color:#b8d9fa}.pills button.active{outline:2px solid #87c9ff}.row label{width:105px}.row input{flex:1}.row output{width:32px}.gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(118px,1fr));gap:8px}.gallery a{border:1px solid var(--line);border-radius:8px;overflow:hidden;color:var(--text);font-size:11px}.gallery img{display:block;width:100%;aspect-ratio:1;object-fit:cover}.gallery span{display:block;padding:6px;overflow-wrap:anywhere}.log{max-height:160px;overflow:auto;color:var(--muted)}@media(max-width:760px){.wrap{padding:11px}.grid{grid-template-columns:1fr}}</style><main class="wrap"><header class="top"><div><b style="font-size:20px">Metech Camera</b><div class="muted">OV5640 · Trạm timelapse</div></div><b id="online" role="status">Đang kết nối</b></header><div class="grid"><section class="card camera"><div class="head"><b>Góc nhìn trực tiếp</b><span class="muted" id="previewlabel">SXGA</span></div><div class="live"><img id="cam" alt="Ảnh xem trước trực tiếp từ camera"></div><div class="actions"><button class="primary" id="capture" disabled>Lưu ảnh QSXGA</button><span class="note" id="notice" role="status"></span></div></section><aside class="card"><div class="head"><b>Thiết bị</b><span id="up" class="muted">-</span></div><div class="stats"><div class="stat">microSD<b id="sd">-</b></div><div class="stat">Ảnh lưu<b id="count">-</b></div><div class="stat">Dung lượng trống<b id="space">-</b></div><div class="stat">Lỗi chụp<b id="fails">-</b></div></div><p class="address"><label for="apip">Recovery AP</label><input class="ip" id="apip" readonly><button data-copy="apip" disabled>Sao chép AP</button></p><p class="address"><label for="lanip">LAN Wi-Fi</label><input class="ip" id="lanip" readonly><button data-copy="lanip" disabled>Sao chép LAN</button></p><p class="note" id="copynote" role="status"></p></aside></div><section class="card"><div class="head"><b>Timelapse tự động</b><span id="tlstate" class="muted" role="status">Đang tải…</span></div><div class="actions"><label for="interval">Khoảng chụp</label><select id="interval"><option>5</option><option>10</option><option>20</option><option>30</option><option>60</option></select><span>giây</span><label for="limit">Giới hạn ảnh</label><input id="limit" type="number" min="0" value="0"><button class="primary" id="tlstart" disabled>Bắt đầu</button><button id="tlstop" disabled>Dừng</button></div><p class="note" id="tlnote" role="status">0 = không giới hạn. Dừng an toàn khi thẻ còn dưới 256 MB; không tự xóa ảnh.</p></section><section class="card"><div class="head"><b>Tốc độ xem trước</b><span id="fps" class="muted">- FPS thực tế</span></div><div class="pills"><button data-mode="eco">Tiết kiệm · SXGA</button><button data-mode="normal">Bình thường · SXGA</button><button data-mode="smooth">Mượt · VGA</button><button data-mode="fast">Nhanh · QVGA</button></div></section><details class="card"><summary>Điều chỉnh camera</summary><div class="pills"><button data-profile="auto">Tự động</button><button data-profile="bright">Xưởng tối</button><button data-profile="neutral">Trung tính</button></div><div id="sliders"></div><div class="pills"><label><input type="checkbox" data-setting="awb"> Tự cân bằng trắng</label><label><input type="checkbox" data-setting="exposure"> Tự phơi sáng</label><label><input type="checkbox" data-setting="gain"> Tự tăng độ nhạy</label></div><div class="actions"><span class="note" id="settingsnote" role="status">Đang tải…</span><button class="primary" id="savesettings">Lưu cấu hình này</button></div></details><section class="card"><div class="head"><b>Sức khỏe vận hành</b><button id="refresh">Tải lại</button></div><div class="stats"><div class="stat">Ước lượng ảnh còn lại<b id="left">-</b></div><div class="stat">Tệp dở đã dọn<b id="tmp">-</b></div></div><ul class="log" id="events"><li>Đang tải nhật ký…</li></ul></section><section class="card"><div class="head"><b>Ảnh trên thẻ</b><span id="gallerynote" class="note" role="status">Đang tải…</span></div><div class="gallery" id="gallery"></div></section><details class="card"><summary>Thiết lập Wi-Fi nhà</summary><form id="wf" class="actions"><label for="ssid">Tên Wi-Fi</label><input id="ssid" name="ssid" required><label for="password">Mật khẩu</label><input id="password" name="password" type="password"><button class="primary">Lưu và kết nối</button></form><p class="note" id="wifinote" role="status"></p></details></main><script>'use strict';const $=s=>document.querySelector(s),cam=$('#cam'),sliders=[['brightness','Độ sáng',-2,2],['contrast','Tương phản',-2,2],['saturation','Màu',-2,2],['sharpness','Độ nét',-2,2],['quality','Chất lượng JPEG',8,20]];let delay=400,pt,pbusy=false,pe=0,poller,polling=false,lastEvents=0;const msg=e=>e instanceof Error?e.message:String(e);async function req(url,data){const c=new AbortController(),t=setTimeout(()=>c.abort(),15000);try{const r=await fetch(url,{cache:'no-store',signal:c.signal,...(data===undefined?{}:{method:'POST',body:data instanceof FormData?data:new URLSearchParams(data)})});if(!r.ok)throw Error(await r.text()||'HTTP '+r.status);return(r.headers.get('content-type')||'').includes('json')?r.json():r.text()}finally{clearTimeout(t)}}function next(){clearTimeout(pt);if(document.hidden||pbusy)return;pbusy=true;cam.src='/snapshot.jpg?t='+Date.now()}function done(ok){pbusy=false;pe=ok?0:Math.min(5,pe+1);if(!document.hidden)pt=setTimeout(next,ok?delay:Math.min(15000,1200*2**(pe-1)))}cam.onload=()=>done(true);cam.onerror=()=>done(false);function fmt(n){return n>=1e9?(n/1e9).toFixed(1)+' GB':n>=1e6?(n/1e6).toFixed(0)+' MB':n+' B'}function address(id,x){const ok=x&&x.ip&&x.ip!=='-';$(id).value=ok?'http://'+x.ip+'/':'';$('[data-copy="'+id.slice(1)+'"]').disabled=!ok}function up(s){$('#up').textContent='Hoạt động '+Math.floor(s.uptime_s/60)+' phút';$('#sd').textContent=s.sd_ready?'Sẵn sàng':'Chưa sẵn sàng';$('#count').textContent=s.images+' ảnh';$('#space').textContent=fmt(s.sd_free_bytes)+' / '+fmt(s.sd_total_bytes);$('#fails').textContent=s.capture_failures;$('#left').textContent=Number(s.estimated_images_left).toLocaleString('vi-VN');$('#tmp').textContent=s.tmp_cleaned;$('#capture').disabled=!s.sd_ready;address('#apip',s.ap);address('#lanip',s.lan);delay=Math.max(100,s.preview.delay_ms||400);$('#fps').textContent=(s.preview.fps_x10/10).toFixed(1)+' FPS thực tế';$('#previewlabel').textContent=s.preview.mode.toUpperCase();document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===s.preview.mode));$('#online').textContent='Đã kết nối'}async function status(){try{up(await req('/api/status'))}catch(e){$('#online').textContent='Mất kết nối';$('#capture').disabled=true}}function setUI(s){sliders.forEach(([n])=>{const x=$('#'+n);x.value=s[n];x.nextElementSibling.textContent=s[n]});['awb','exposure','gain'].forEach(n=>$('[data-setting="'+n+'"]').checked=!!s[n])}sliders.forEach(([n,label,min,max])=>{const d=document.createElement('div'),l=document.createElement('label'),x=document.createElement('input'),o=document.createElement('output');d.className='row';l.htmlFor=n;l.textContent=label;x.id=n;x.dataset.setting=n;x.type='range';x.min=min;x.max=max;x.oninput=()=>o.textContent=x.value;d.append(l,x,o);$('#sliders').append(d)});async function settings(){try{setUI(await req('/api/camera-settings'));$('#settingsnote').textContent='Đã áp dụng · chưa lưu sau khi khởi động lại.'}catch(e){$('#settingsnote').textContent='Lỗi: '+msg(e)}}document.addEventListener('change',async e=>{const n=e.target.dataset.setting;if(!n)return;e.target.disabled=true;try{setUI(await req('/api/camera-settings',{name:n,value:e.target.type==='checkbox'?(e.target.checked?1:0):e.target.value}));$('#settingsnote').textContent='Đã áp dụng · chưa lưu sau khi khởi động lại.'}catch(e){$('#settingsnote').textContent='Lỗi: '+msg(e)}finally{e.target.disabled=false}});document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{setUI(await req('/api/camera-profile',{profile:b.dataset.profile}))}catch(e){$('#settingsnote').textContent='Lỗi: '+msg(e)}finally{b.disabled=false}});$('#savesettings').onclick=async()=>{try{$('#settingsnote').textContent=await req('/api/camera-settings/save',{})}catch(e){$('#settingsnote').textContent='Lỗi: '+msg(e)}};async function tl(){try{const s=await req('/api/timelapse');$('#tlstate').textContent=s.active?'Đang chụp '+s.taken+(s.limit?'/'+s.limit:'')+' ảnh sau '+s.next_s+' giây':s.state+(s.error?' - '+s.error:'');$('#tlstart').disabled=s.active;$('#tlstop').disabled=!s.active}catch(e){$('#tlstate').textContent='Không tải được trạng thái'}}async function act(start){try{await req('/api/timelapse/'+(start?'start':'stop'),start?{interval:$('#interval').value,limit:$('#limit').value||0}:{});$('#tlnote').textContent=start?'Đã bắt đầu timelapse.':'Đã yêu cầu dừng an toàn.'}catch(e){$('#tlnote').textContent='Lỗi: '+msg(e)}finally{poll()}}$('#tlstart').onclick=()=>act(true);$('#tlstop').onclick=()=>act(false);document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=async()=>{try{const s=await req('/api/preview',{mode:b.dataset.mode});delay=s.delay_ms||delay;poll()}catch(e){$('#notice').textContent='Lỗi xem trước: '+msg(e)}});async function events(){try{const d=await req('/api/events'),a=d.events.map(x=>{const li=document.createElement('li');li.textContent=x.at_s+' giây - '+x.text;return li});if(!a.length){const li=document.createElement('li');li.textContent='Chưa có nhật ký.';a.push(li)}$('#events').replaceChildren(...a)}catch(e){const li=document.createElement('li');li.textContent='Không tải được nhật ký.';$('#events').replaceChildren(li)}}async function gallery(){try{const d=await req('/api/gallery'),a=d.images.map(n=>{const x=document.createElement('a'),i=document.createElement('img'),z=document.createElement('span');x.target='_blank';x.rel='noopener';x.href='/image/'+encodeURIComponent(n);i.loading='lazy';i.src=x.href;i.alt=n;z.textContent=n;x.append(i,z);return x});if(!a.length){const x=document.createElement('span');x.textContent='Chưa có ảnh.';a.push(x)}$('#gallery').replaceChildren(...a);$('#gallerynote').textContent=d.total+' ảnh'}catch(e){$('#gallerynote').textContent='Không tải được thư viện: '+msg(e)}}$('#capture').onclick=async()=>{try{$('#capture').disabled=true;$('#notice').textContent='Đang lưu…';$('#notice').textContent='Đã lưu: '+await req('/api/capture',{});await gallery()}catch(e){$('#notice').textContent='Lỗi: '+msg(e)}finally{poll()}};$('#refresh').onclick=()=>{lastEvents=0;poll();gallery()};$('#wf').onsubmit=async e=>{e.preventDefault();try{$('#wifinote').textContent=await req('/api/wifi',new FormData(e.target));$('#password').value=''}catch(x){$('#wifinote').textContent='Lỗi: '+msg(x)}};document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const x=$('#'+b.dataset.copy);try{if(navigator.clipboard&&isSecureContext){await navigator.clipboard.writeText(x.value);$('#copynote').textContent='Đã sao chép địa chỉ.';return}}catch(e){}x.focus();x.select();try{$('#copynote').textContent=document.execCommand('copy')?'Đã sao chép địa chỉ.':'Đã chọn địa chỉ. Nhấn Ctrl+C để sao chép.'}catch(e){$('#copynote').textContent='Đã chọn địa chỉ. Nhấn Ctrl+C để sao chép.'}});async function poll(){clearTimeout(poller);if(document.hidden||polling)return;polling=true;try{await status();await tl();if(Date.now()-lastEvents>=8000){await events();lastEvents=Date.now()}}finally{polling=false;if(!document.hidden)poller=setTimeout(poll,2000)}}document.addEventListener('visibilitychange',()=>{clearTimeout(poller);clearTimeout(pt);if(!document.hidden){poll();next()}});if(!document.hidden){poll();settings();gallery();next()}</script>)HTML";
